              "direction": "input",
              "binding": "vars.fetchPOData1.output.totalAmount"
            },
            {
              "id": "decision",
              "label": "Decision",
              "type": "string",
              "direction": "output",
              "variable": "vars.decision",
              "required": true
            },
            {
              "id": "notes",
              "label": "Notes",
              "type": "string",
              "direction": "output",
              "variable": "vars.notes",
              "required": false
            }
          ],
          "outcomes": [
            { "id": "approve", "name": "Approve", "type": "string", "isPrimary": true, "action": "Continue" },
            { "id": "reject", "name": "Reject", "type": "string", "isPrimary": false, "action": "End" }
          ]
        }
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Task result data",
          "source": "=result",
          "var": "output",
          "properties": {
            "decision": { "type": "string" },
            "notes": { "type": "string" },
            "Action": { "type": "string", "enum": ["Approve", "Reject"], "default": "Approve" }
          }
        },
        "status": {
          "type": "string",
          "description": "Task completion status",
          "source": "=result.Action",
          "var": "status",
          "enum": ["Approve", "Reject"],
          "default": "Approve"
        }
      }
    },
    {
      "id": "checkDecision1",
      "type": "core.logic.decision",
      "typeVersion": "1.2",
      "display": { "label": "Approved?" },
      "inputs": {
        "expression": "$vars.poReview1.status === \"Approve\"",
        "trueLabel": "Approve",
        "falseLabel": "Reject"
      }
    },
    {
      "id": "logApproval1",
      "type": "core.action.script",
      "typeVersion": "1.1",
      "display": { "label": "Log PO Approved" },
      "inputs": {
        "script": "return {\n  message: \"PO approved\",\n  poNumber: $vars.fetchPOData1.output.poNumber,\n  approvedBy: $vars.poReview1.output.decision,\n  notes: $vars.poReview1.output.notes\n};"
