      "outputs": {
        "output": {
          "type": "object",
          "description": "Approval log entry",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "endApproved1",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": { "label": "PO Approved" },
      "inputs": {}
    },
